-- Expand teaching content with audience, syllabus, outcomes, feedback, and project resources.
UPDATE site_sections
SET title = 'Graduate cloud computing through hands-on practice',
    summary = 'Course design, AWS projects, student outcomes, and feedback from graduate teaching at Yeshiva University.',
    content_json = '{"school":"The Katz School of Science and Health at Yeshiva University","audience":"Graduate students in AI, Data Science, and Cybersecurity programs","course":"Adjunct Professor · January 2025 — present","body":"I teach a graduate Cloud Computing course that connects foundational concepts with practical AWS implementation. Students study compute, networking, storage, databases, big data, AI, serverless systems, containers, security, and resilient architecture, then complete a hands-on project for each major topic.","outcomes":["Explain cloud computing models, characteristics, and shared responsibility","Design networking and compute foundations for scalable cloud applications","Work with storage, relational and NoSQL databases, and analytics services","Build with containers, serverless services, APIs, and infrastructure as code","Evaluate security, compliance, availability, and cost trade-offs","Use core AWS services through practical projects and architecture exercises","Build the foundation needed to prepare for AWS Cloud Practitioner certification"],"syllabus":[{"classNumber":1,"title":"Cloud computing foundations","content":"Definitions, characteristics, service models, and delivery models","project":"Set up an AWS account"},{"classNumber":2,"title":"AWS foundations","content":"IAM, global infrastructure, pricing, CLI, APIs, and SDKs","project":"Create IAM users and policies; install the AWS CLI"},{"classNumber":3,"title":"Cloud-enabling technologies","content":"Networking, virtualization, web technologies, and containerization","project":"Deploy a web application on Amazon EC2"},{"classNumber":4,"title":"Amazon VPC","content":"VPC design, network ACLs, security groups, and shared responsibility","project":"Build a custom AWS VPC"},{"classNumber":5,"title":"Resilient cloud architecture","content":"Scaling, high availability, and fault tolerance","project":"Configure security groups and network ACLs"},{"classNumber":6,"title":"Load balancing and scaling","content":"Elastic Load Balancing and Auto Scaling","project":"Build a multi-component VPC architecture"},{"classNumber":7,"title":"Storage, databases, and analytics","content":"Storage models, database categories, and data analytics foundations","project":"Architecture comparison exercise"},{"classNumber":8,"title":"AWS storage and databases","content":"EBS, S3, RDS, DynamoDB, and CloudFormation","project":"Connect to RDS and use CloudFormation templates"},{"classNumber":9,"title":"DNS and content delivery","content":"DNS, Route 53, CDN architecture, and CloudFront","project":"Create hosted zones and serve an S3 website through CloudFront"},{"classNumber":10,"title":"Containers","content":"Containers, Amazon ECR, and Amazon ECS","project":"Containerize a Django application and deploy it with ECS"},{"classNumber":11,"title":"Serverless applications","content":"AWS Lambda and API Gateway","project":"Create a Lambda function and expose it through API Gateway"},{"classNumber":12,"title":"Big data","content":"Redshift, EMR, Glue, and Athena","project":"Analyze Application Load Balancer logs with Athena"},{"classNumber":13,"title":"Cloud security","content":"KMS, CloudHSM, WAF, Shield, and GuardDuty","project":"Create WAF rules and investigate GuardDuty"},{"classNumber":14,"title":"AI in the cloud","content":"Rekognition, Transcribe, Translate, Comprehend, Lex, and Textract","project":"Build an application with Rekognition and Textract"},{"classNumber":15,"title":"Well-Architected design","content":"The six pillars of the AWS Well-Architected Framework","project":"Design and build a three-tier architecture"}],"feedbackSummary":"The Spring 2026 cohort, with a 50% response rate, rated every evaluated category between 4.4 and 4.6. Students consistently highlighted the practical, interactive approach to cloud and AI.","feedbackHighlights":["Hands-on labs, live coding, and practical projects made the material engaging","Class discussions and a strong learning community supported understanding","AWS and cloud foundations increased confidence to pursue certification","Applying AI tools within cloud workflows was especially valuable"],"feedbackImprovements":["Provide additional time for hands-on labs and a broader set of tools","Continue tightening pacing so every planned topic receives enough depth","Add more comparison with cloud providers beyond AWS","Align selected exercises even more closely with certification preparation"],"links":[{"label":"Hands-on AWS projects","href":"https://github.com/oskarcode/yuteaching"},{"label":"Teaching platform","href":"https://cloudteaching.oskarcode.com/"},{"label":"Notebook exercises","href":"https://github.com/oskarcode/python_bootcamp"},{"label":"Student review summary","href":"https://www.smartevals.com/GreatestHits/YouAreAwesome.aspx?P=216974140"}]}',
    updated_at = CURRENT_TIMESTAMP
WHERE id = 'teaching';
